function registerIntegrationCommands(e){let{appRoot:t,logger:n,program:r}=e,i=r.command(`integration`,{hidden:!0});i.command(`setup <kind>`).option(`-y, --yes`).action(async(e,r)=>{let{runIntegrationSetupCommand:i}=await import(`./integration-setup.js`);await i(n,t,e,{yes:r.yes})}),i.command(`connect <slug> <service> [canonical-name]`).option(`-y, --yes`).action(async(e,r,i)=>{let{runIntegrationConnectCommand:a}=await import(`./integration-connect.js`);await a(n,t,e,r,i)})}export{registerIntegrationCommands};